    // Test 1: or_comm — P \/ Q == Q \/ P (all 4 combinations)
    var t1 = true
    var p = false; var q = false
    if (p || q) != (q || p) { t1 = false }
    p = true; q = false
    if (p || q) != (q || p) { t1 = false }
    p = false; q = true
    if (p || q) != (q || p) { t1 = false }
